using System;
using System.Collections.Generic;
using System.Linq;
using AICad.Contracts;
using JsonUtil=AICad.Contracts.Json;
using AICad.Geometry;
using Autodesk.AutoCAD.ApplicationServices;
using Autodesk.AutoCAD.DatabaseServices;
using Autodesk.AutoCAD.Geometry;
using Newtonsoft.Json.Linq;
namespace AICad.Bridge;
internal static partial class Reader {
 internal static List<TaskInfo> Scan(Document d){var tasks=new List<TaskInfo>();using var tx=d.Database.TransactionManager.StartOpenCloseTransaction();var outputs=OutputAnchors.Scan(d.Database,tx);var table=(BlockTable)tx.GetObject(d.Database.BlockTableId,OpenMode.ForRead);var model=(BlockTableRecord)tx.GetObject(table[BlockTableRecord.ModelSpace],OpenMode.ForRead);int scanned=0;foreach(ObjectId id in model){if(++scanned>100000)throw new CadException("SCAN_LIMIT","Limit 100,000 entities per scan.");if(!(tx.GetObject(id,OpenMode.ForRead) is BlockReference block))continue;var def=(BlockTableRecord)tx.GetObject(block.IsDynamicBlock?block.DynamicBlockTableRecord:block.BlockTableRecord,OpenMode.ForRead);if(!def.Name.Equals("AI_TASK",StringComparison.OrdinalIgnoreCase)&&!def.Name.StartsWith("AI_TASK_SOURCE_",StringComparison.OrdinalIgnoreCase))continue;var attrs=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);foreach(ObjectId aid in block.AttributeCollection){var a=(AttributeReference)tx.GetObject(aid,OpenMode.ForRead);if(attrs.ContainsKey(a.Tag))throw new CadException("INVALID_TASK","Duplicate attribute tags.");attrs[a.Tag]=a.TextString;}string Get(string key,string fallback="")=>attrs.TryGetValue(key,out var v)?v:fallback;var task=new TaskInfo{TaskId=Get("TASK_ID"),SkillId=Get("SKILL_ID"),Prompt=Get("PROMPT"),TemplateId=Get("TEMPLATE_ID","STARTER"),Handle=block.Handle.ToString(),Status=Get("STATUS","PENDING"),Dependencies=Get("DEPENDS_ON").Split(new[]{',',';'},StringSplitOptions.RemoveEmptyEntries).Select(x=>x.Trim()).ToList()};if(outputs.TryGetValue(task.TaskId,out var anchors)){if(anchors.Count!=1||Math.Abs(anchors[0].Z)>1e-6)task.Warnings.Add("Diem dat ket qua bi trung hoac khong o mat phang XY.");else task.OutputPoint=new Point2(anchors[0].X,anchors[0].Y);}if(Get("OUTPUT_REQUIRED")=="1"&&task.OutputPoint==null)task.Warnings.Add("Thieu diem AI_OUTPUT_POINT cua khung.");var boundaries=new List<Polyline>();var actual=(BlockTableRecord)tx.GetObject(block.BlockTableRecord,OpenMode.ForRead);foreach(ObjectId child in actual)if(tx.GetObject(child,OpenMode.ForRead) is Polyline pl&&pl.Closed)boundaries.Add(pl);if(boundaries.Count!=1)task.Warnings.Add("AI_TASK requires exactly one closed polyline boundary.");else{var poly=boundaries[0];for(int i=0;i<poly.NumberOfVertices;i++){if(Math.Abs(poly.GetBulgeAt(i))>1e-10){task.Warnings.Add("Curved boundary not supported.");break;}var p=poly.GetPoint3dAt(i).TransformBy(block.BlockTransform);if(Math.Abs(p.Z)>1e-6)task.Warnings.Add("Boundary must be WCS XY.");task.Scope.Add(new Point2(p.X,p.Y));}try{Validation.Scope(task.Scope);}catch(CadException e){task.Warnings.Add(e.Message);}}try{JsonUtil.Name(task.TaskId);JsonUtil.Name(task.SkillId);JsonUtil.Name(task.TemplateId);}catch(CadException e){task.Warnings.Add(e.Message);}tasks.Add(task);if(tasks.Count>100)throw new CadException("TASK_LIMIT","Maximum 100 task blocks per DWG in v0.1.");}foreach(var group in tasks.GroupBy(t=>t.TaskId).Where(g=>g.Count()>1))foreach(var t in group)t.Warnings.Add("Duplicate TASK_ID.");foreach(var t in tasks)foreach(string dep in t.Dependencies)if(dep==t.TaskId||!tasks.Any(x=>x.TaskId==dep))t.Warnings.Add("Missing or self dependency: "+dep);for(int i=0;i<tasks.Count;i++)for(int j=i+1;j<tasks.Count;j++){var a=tasks[i];var b=tasks[j];if(a.Scope.Count<3||b.Scope.Count<3)continue;if(Overlap(a.Scope,b.Scope)){a.Warnings.Add("Overlapping task scope: "+b.TaskId);b.Warnings.Add("Overlapping task scope: "+a.TaskId);}}return tasks;}
 internal static bool Overlap(List<Point2> a,List<Point2> b){foreach(var polygon in new[]{a,b})for(int i=0;i<polygon.Count;i++){var p=polygon[i];var q=polygon[(i+1)%polygon.Count];double nx=-(q.Y-p.Y),ny=q.X-p.X;if(nx*nx+ny*ny<1e-12)continue;var aa=a.Select(v=>v.X*nx+v.Y*ny);var bb=b.Select(v=>v.X*nx+v.Y*ny);if(aa.Max()<=bb.Min()+1e-6||bb.Max()<=aa.Min()+1e-6)return false;}return true;}
 internal static JObject ReadLegacy(Document d,JObject args){int offset=args.Value<int?>("offset")??0,limit=args.Value<int?>("limit")??100;if(offset<0||limit<1||limit>200)throw new CadException("INVALID_PAGE","limit must be 1–200.");using var tx=d.Database.TransactionManager.StartOpenCloseTransaction();var bt=(BlockTable)tx.GetObject(d.Database.BlockTableId,OpenMode.ForRead);var ms=(BlockTableRecord)tx.GetObject(bt[BlockTableRecord.ModelSpace],OpenMode.ForRead);var rows=new JArray();int index=0;bool more=false;foreach(ObjectId id in ms){if(index++<offset)continue;if(rows.Count==limit){more=true;break;}var e=tx.GetObject(id,OpenMode.ForRead) as Entity;if(e==null)continue;var row=new JObject{["handle"]=e.Handle.ToString(),["type"]=e.GetType().Name,["layer"]=e.Layer};try{var bounds=e.GeometricExtents;row["bounds"]=new JObject{["minX"]=bounds.MinPoint.X,["minY"]=bounds.MinPoint.Y,["maxX"]=bounds.MaxPoint.X,["maxY"]=bounds.MaxPoint.Y};}catch(Autodesk.AutoCAD.Runtime.Exception){}rows.Add(row);}return new JObject{["entities"]=rows,["nextOffset"]=more?new JValue(offset+limit):JValue.CreateNull()};}
}
